T v0_y = vertices[v0_idx * 3 + 1];
T v0_z = vertices[v0_idx * 3 + 2];
T v1_x = vertices[v1_idx * 3];
T v1_y = vertices[v1_idx * 3 + 1];
T v1_z = vertices[v1_idx * 3 + 2];
T v2_x = vertices[v2_idx * 3];
T v2_y = vertices[v2_idx * 3 + 1];
T v2_z = vertices[v2_idx * 3 + 2];

// Compute axis-aligned bounding box
T min_x = std::min({v0_x, v1_x, v2_x});
T min_y = std::min({v0_y, v1_y, v2_y});
T min_z = std::min({v0_z, v1_z, v2_z});
T max_x = std::max({v0_x, v1_x, v2_x});
T max_y = std::max({v0_y, v1_y, v2_y});
T max_z = std::max({v0_z, v1_z, v2_z});

// Create temporary real3 objects and assign to outputs
*bmin = real3<T>(min_x, min_y, min_z);
*bmax = real3<T>(max_x, max_y, max_z);
